#ai: cppcheck project audit. The compile database is generated by the lint
#   preset. Errors are blocking; warnings are reported for triage (cppcheck's
#   OOM/bitfield checks are intentionally advisory). Vendored raylib and ImGui
#   are filtered out.
"""Run cppcheck over gX sources and report errors/warnings."""

import argparse
import collections
import os
import shutil
import subprocess
import sys
import tempfile
import xml.etree.ElementTree as ET
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
DB_DIR = ROOT / "build" / "lint"


def ensure_database():
    if (DB_DIR / "compile_commands.json").is_file():
        return True
    result = subprocess.run(
        ["cmake", "-B", str(DB_DIR), "-DCMAKE_BUILD_TYPE=Debug",
         "-DCMAKE_EXPORT_COMPILE_COMMANDS=ON", str(ROOT)],
        capture_output=True, text=True, check=False)
    return result.returncode == 0 and (DB_DIR / "compile_commands.json").is_file()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--strict", action="store_true",
                        help="exit 1 when cppcheck reports errors")
    parser.add_argument("--strict-warnings", action="store_true",
                        help="also fail on warnings")
    args = parser.parse_args()
    cppcheck = shutil.which("cppcheck")
    if not cppcheck:
        print("CPPCHECK: SKIP — cppcheck not installed")
        return 0
    if not ensure_database():
        print("CPPCHECK: FAIL — compile database unavailable")
        return 2

    scratch = Path(os.environ.get("GX_SCRATCH", "/tmp/opencode"))
    scratch.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="gx_cppcheck_", dir=scratch) as directory:
        xml_path = Path(directory) / "cppcheck.xml"
        command = [
            cppcheck, "--project=" + str(DB_DIR / "compile_commands.json"),
            "--enable=warning", "--inline-suppr",
            "--suppress=missingIncludeSystem", "--suppress=unusedFunction",
            "--error-exitcode=0", "--xml", "--xml-version=2", "-j",
            str(min(4, os.cpu_count() or 2)),
        ]
        result = subprocess.run(command, capture_output=True, text=True,
                                check=False)
        with open(xml_path, "w", encoding="utf-8") as stream:
            stream.write(result.stderr)
        root = ET.parse(xml_path).getroot()

    errors = []
    warnings = []
    warning_ids = collections.Counter()
    root_prefix = str(ROOT.resolve()) + os.sep
    for error in root.iter("error"):
        location = error.find("location")
        path = location.get("file", "") if location is not None else ""
        if path.startswith(root_prefix):
            path = path[len(root_prefix):]
        if not path.startswith("src/") or path.startswith(
                ("src/external/", "src/tools/imgui/")):
            continue
        text = "%s:%s %s [%s] %s" % (
            path, location.get("line", "?"), error.get("severity", "?"),
            error.get("id", "?"), error.get("msg", ""))
        if error.get("severity") == "error":
            errors.append(text)
        else:
            warnings.append(text)
            warning_ids[error.get("id", "?")] += 1

    print("CPPCHECK: %d error(s), %d warning(s) in gX sources" % (
        len(errors), len(warnings)))
    for text in errors[:40]:
        print("  ERROR " + text)
    for text in warnings[:20]:
        print("  warn  " + text)
    if len(warnings) > 20:
        print("  ... %d more warnings" % (len(warnings) - 20))
    if warning_ids:
        print("  warning classes: " + ", ".join(
            "%s=%d" % item for item in warning_ids.most_common(10)))

    if errors and args.strict:
        print("CPPCHECK: FAIL")
        return 1
    if warnings and args.strict_warnings:
        print("CPPCHECK: FAIL (warnings)")
        return 1
    print("CPPCHECK: PASS" if not errors else "CPPCHECK: advisory errors")
    return 0


if __name__ == "__main__":
    sys.exit(main())
